// src/util/allocateArray.ts
function allocateArray(size, data) {
  if (data.length > size)
    throw new RangeError(`Tried to fill ${data.length} bytes into a ${size}-byte array`);
  let array = new Uint8Array(size);
  for (var i = 0;i < data.length; i++) {
    array[i] = data[i];
  }
  return array;
}

// src/util/dataConvert.ts
function dataToBase64(data) {
  return btoa(String.fromCharCode.apply(null, data));
}
function dataToHex(data) {
  return Array.from(data, (i) => i.toString(16).padStart(2, "0")).join("");
}

// src/util/Numbers.ts
function randomizeUint8Array(arr) {
  if (!(arr instanceof Uint8Array)) {
    throw new TypeError("Expected a Uint8Array");
  }
  function randomize() {
    for (let i = 0;i < arr.length; i++) {
      arr[i] = Math.floor(Math.random() * 256);
    }
  }
  if (typeof window !== "undefined") {
    if (window.crypto && window.crypto.getRandomValues) {
      window.crypto.getRandomValues(arr);
    } else
      randomize();
  } else {
    randomize();
  }
  return arr;
}

