// src/util/ModelLoader.ts
//! NOTE: THIS ASSUMES THE ROOT IS THE PUBLIC FOLDER
var root = "/";
var gltfLoader = new GLTFLoader;
gltfLoader.setMeshoptDecoder(MeshoptDecoder);
var imageLoader = new (_THREE()).ImageBitmapLoader;
function makeModelPath(gender, modelName) {
  return `${root}assets/models/miiBody${gender}_${modelName}.glb`;
}
async function loadBodyModel(modelPath) {
  const model = await gltfLoader.loadAsync(modelPath);
  var mixer = new (_THREE()).AnimationMixer(model.scene);
  const scene = model.scene;
  if (model.animations.length > 0) {
    const idleClip = model.animations[0];
    const idleAnim = mixer.clipAction(idleClip, scene);
    idleAnim.stop();
    try {
      const clip = model.animations.find((a) => a.name === "Pose.01");
      const anim = mixer.clipAction(clip, scene);
      anim.play();
      anim.timeScale = 0;
      anim.paused = true;
      mixer.update(0);
    } catch (e) {}
  } else
    console.warn("Body model has no animations");
  return model;
}
var bodyType = "wiiu";
async function loadBodyModels(input, alsoLoadStreetPass = false) {
  if (Object.keys(bodyModels).length > 0) {
    bodyModels = {};
  }
  bodyType = input || await import_localforage2.default.getItem("settings_bodyModel") || "wiiu";
  bodyModelName = bodyType;
  if (bodyType === "streetpass" /* StreetPass */) {
    isStreetPassBody = true;
  }
  if (bodyModels.highM) {
    bodyModels.highM.scene.traverse((o) => {
      if (o.isMesh) {
        o.dispose();
      }
    });
  }
  if (bodyModels.highF) {
    bodyModels.highF.scene.traverse((o) => {
      if (o.isMesh) {
        o.dispose();
      }
    });
  }
  bodyModels.highM = await loadBodyModel(makeModelPath("M", bodyType));
  bodyModels.highF = await loadBodyModel(makeModelPath("F", bodyType));
  if (alsoLoadStreetPass) {
    bodyModels.lowM = await loadBodyModel(makeModelPath("M", "streetpass"));
    bodyModels.lowF = await loadBodyModel(makeModelPath("F", "streetpass"));
  }
}
async function loadHatModels() {
  hatModels = [];
  const data = await fetch(root + "assets/models/hat_models_bundle.zip").then((j) => j.blob());
  const zip = await import_jszip.default.loadAsync(data);
  let promises = [];
  const fileList = Object.keys(zip.files);
  for (const file of fileList) {
    promises.push(zip.files[file].async("blob"));
  }
  const resolves = await Promise.all(promises);
  for (let i2 = 0;i2 < fileList.length; i2++) {
    console.log("File:", fileList[i2]);
    const url = URL.createObjectURL(resolves[i2]);
    const gltf = await gltfLoader.loadAsync(url);
    hatModels[i2] = gltf.scene;
    URL.revokeObjectURL(url);
  }
}
async function loadClothesTextures() {
  clothesTextures = {};
  const data = await fetch(root + "assets/images/mii_clothes_textures_bundle.zip").then((j) => j.blob());
  console.log("Got it");
  const zip = await import_jszip.default.loadAsync(data);
  console.log("Got zip");
  let promises = [];
  const fileList = Object.keys(zip.files);
  for (const file of fileList) {
    promises.push(zip.files[file].async("blob"));
  }
  const resolves = await Promise.all(promises);
  console.log("Got files");
  for (let i2 = 0;i2 < fileList.length; i2++) {
    const url = URL.createObjectURL(resolves[i2]);
    let result;
    console.log("Loading texture", fileList[i2]);
    result = new (_THREE()).CanvasTexture(await imageLoader.loadAsync(url));
    console.log("Loading texture done");
    const fileName = fileList[i2].split(".");
    fileName.pop();
    clothesTextures[fileName.join(".")] = result;
    console.log("Loading " + fileName.join("."));
    URL.revokeObjectURL(url);
  }
  console.log("Done");
}
var bodyModels = {
  highM: null,
  highF: null,
  lowM: null,
  lowF: null
};
var bodyModelName = "wiiu";
var hatModels = [];
var clothesTextures = {};
var isStreetPassBody = false;
var isStreetPass = () => isStreetPassBody;
var getBodyModels = () => bodyModels;
var getHatModels = () => hatModels;
var getLoadedBodyModelName = () => bodyModelName;
