// src/pocketpass/RendererFFL.ts
var fflModule;
var preparePromise = null;
var getPocketPassFFL = () => fflModule;
function preparePocketPassFFL() {
  if (preparePromise)
    return preparePromise;
  preparePromise = (async () => {
    fflModule = await import_ffl_emscripten.default({
      locateFile: (path) => new URL(`/dist/${path}`, location.origin).href
    });
    await Promise.all([
      loadBodyModels("wiiu"),
      loadHatModels(),
      loadClothesTextures()
    ]);
    const response = await fetch("/FFLResHigh.dat", {
      cache: "force-cache",
      credentials: "same-origin"
    });
    if (!response.ok) {
      throw new Error(`FFL resource unavailable (${response.status})`);
    }
    fflModule = (await initializeFFL(response, fflModule)).module;
  })();
  return preparePromise;
}

